SELECT t.rec_id AS record_id,t."交付得分" AS "交付得分",t."交付权重" AS "交付权重",t."供应商" AS "供应商",t."创建时间" AS "创建时间",t."协同得分" AS "协同得分",t."协同权重" AS "协同权重",t."工厂" AS "工厂",t."更新时间" AS "更新时间",t."服务得分" AS "服务得分",t."服务权重" AS "服务权重",t."综合得分" AS "综合得分",t."评价人" AS "评价人",t."评价依据" AS "评价依据",t."评价周期" AS "评价周期",t."评价编号" AS "评价编号",t."质量得分" AS "质量得分",t."质量权重" AS "质量权重",s.rec_id AS supplier_id,s."供应商名称" AS supplier_name,s."国家" AS supplier_country,(s."推广阶段").name AS supplier_stage FROM "SupplierEvaluations" AS t LEFT JOIN "Suppliers" AS s ON t."供应商" @> ARRAY[s.rec_id] INNER JOIN "Members" AS access_member ON (access_member."用户").id = CURRENT_USER_ID() LEFT JOIN "Roles" AS access_role ON access_member."角色编码" = access_role."角色编码" WHERE (access_member."状态").name = '启用' AND ((access_member."角色编码" IS NULL AND (access_member."角色").name IN ('管理员','采购','中央仓','技术','只读')) OR (access_role."启用" = TRUE AND access_role."权限代码" LIKE '%|evaluation.read|%')) ORDER BY t.rec_id ASC LIMIT 500 OFFSET $1